import{_ as l,o as i,c as a,a2 as t}from"./chunks/framework.BXA5Pi9t.js";const d=JSON.parse('{"title":"Ceph User + Dev Monthly Meeting 2024-09-25","description":"","frontmatter":{"title":"Ceph User + Dev Monthly Meeting 2024-09-25","date":"2024-09-25T00:00:00.000Z","updated":"2024-09-26T00:00:00.000Z","tags":["Ceph","分布式存储","CRUSH算法","高可用性","可伸缩性","对象存储"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2024/Ceph_User_+_Dev_Monthly_Meeting_2024-09-25.md","filePath":"posts/2024/Ceph_User_+_Dev_Monthly_Meeting_2024-09-25.md","lastUpdated":1780459816000}'),r={name:"posts/2024/Ceph_User_+_Dev_Monthly_Meeting_2024-09-25.md"};function o(p,e,n,s,h,u){return i(),a("div",null,[...e[0]||(e[0]=[t('<h3 id="ceph-用户及开发者月度会议纪要" tabindex="-1">Ceph 用户及开发者月度会议纪要 <a class="header-anchor" href="#ceph-用户及开发者月度会议纪要" aria-label="Permalink to &quot;Ceph 用户及开发者月度会议纪要&quot;">​</a></h3><h4 id="会议概述" tabindex="-1">会议概述 <a class="header-anchor" href="#会议概述" aria-label="Permalink to &quot;会议概述&quot;">​</a></h4><p>本次Ceph用户及开发者月度会议主要讨论了Ceph分布式存储系统的关键议题，包括禁用扩展模式、碳设计系统在Ceph仪表板中的应用，以及将upmap remap PG remapper集成到平衡器中。会议还涉及了Ceph未来版本计划和技术细节的讨论。</p><h4 id="主要议题" tabindex="-1">主要议题 <a class="header-anchor" href="#主要议题" aria-label="Permalink to &quot;主要议题&quot;">​</a></h4><ol><li><p><strong>禁用扩展模式</strong></p><ul><li><strong>主讲人</strong>：Junior</li><li><strong>内容概要</strong>： <ul><li>定义了扩展集群和扩展模式，解释了其工作原理和应用场景。</li><li>讨论了扩展模式的启用和禁用命令，以及禁用的必要性和相关要求。</li><li>提出了禁用扩展模式的命令和条件，强调了操作的安全性和重要性。</li></ul></li><li><strong>讨论点</strong>： <ul><li>支持擦除编码池在扩展集群中的使用。</li><li>连接模式与经典模式在非扩展集群中的比较。</li></ul></li></ul></li><li><p><strong>碳设计系统在Ceph仪表板中的应用</strong></p><ul><li><strong>主讲人</strong>：Evo MAA</li><li><strong>内容概要</strong>： <ul><li>介绍了碳设计系统的引入背景和目的，强调了其在提高用户体验和开发者效率方面的作用。</li><li>展示了碳设计系统在Ceph仪表板中的应用实例，包括导航栏和数据表的更新。</li><li>讨论了未来将现有功能迁移到碳设计系统的计划。</li></ul></li></ul></li><li><p><strong>将upmap remap PG remapper集成到平衡器中</strong></p><ul><li><strong>主讲人</strong>：会议主持人</li><li><strong>内容概要</strong>： <ul><li>提出了将upmap remap PG remapper工具集成到Ceph平衡器模块的设计提案。</li><li>讨论了集成该功能的动机和潜在的技术挑战。</li><li>强调了该功能对于处理集群中大量 misplaced objects 的重要性。</li></ul></li><li><strong>讨论点</strong>： <ul><li>减少在添加或移除OSD时产生的多次 peering 事件。</li><li>通过增加平衡器模块的优化次数配置来加快处理速度的可能性。</li></ul></li></ul></li></ol><h4 id="决定事项" tabindex="-1">决定事项 <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项&quot;">​</a></h4><ul><li>确认了禁用扩展模式的功能和相关命令。</li><li>碳设计系统将在Ceph仪表板中得到更广泛的应用。</li><li>upmap remap PG remapper将集成到Ceph平衡器模块中，以处理集群中的 misplaced objects。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h4><ul><li>Junior将准备相关的文档和测试，确保禁用扩展模式的功能稳定并准备合并。</li><li>Evo MAA将继续推进碳设计系统在Ceph仪表板中的实施。</li><li>会议主持人将与Dan Vander合作，进一步细化upmap remap PG remapper集成到平衡器模块的设计提案，并计划在未来的Ceph版本中实施。</li></ul><h4 id="其他信息" tabindex="-1">其他信息 <a class="header-anchor" href="#其他信息" aria-label="Permalink to &quot;其他信息&quot;">​</a></h4><ul><li>会议中提到的功能和改进将考虑在未来的Ceph版本中实现，包括tentacle版本。</li><li>社区成员可以通过跟踪相关的GitHub问题和参与讨论来关注和贡献这些功能的开发。</li></ul><p>会议结束时，主持人感谢所有参与者的贡献，并预告了下个月的会议主题。社区成员可以通过Slack频道或电子邮件列表获取更多更新信息。</p>',12)])])}const c=l(r,[["render",o]]);export{d as __pageData,c as default};
